// Test script to verify the /check endpoint
const app = require('./app');
const request = require('supertest');

// Test 1: Valid rule evaluation
async function testValidRule() {
  console.log('Testing valid rule evaluation...');

  const response = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/)
    .expect(200);

  console.log('Response:', JSON.stringify(response.body, null, 2));
  console.log('Result should be true:', response.body.result === true);
}

// Test 2: Invalid rule (missing context)
async function testMissingContext() {
  console.log('\nTesting missing context...');

  const response = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100'
    })
    .expect('Content-Type', /json/)
    .expect(400);

  console.log('Response:', JSON.stringify(response.body, null, 2));
  console.log('Error message should mention missing context:', response.body.error.includes('context'));
}

// Test 3: Invalid rule (missing rule field)
async function testMissingRule() {
  console.log('\nTesting missing rule...');

  const response = await request(app)
    .post('/check')
    .send({
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/)
    .expect(400);

  console.log('Response:', JSON.stringify(response.body, null, 2));
  console.log('Error message should mention missing rule:', response.body.error.includes('rule'));
}

// Test 4: Rule evaluation error
async function testRuleError() {
  console.log('\nTesting rule evaluation error...');

  const response = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount >',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/)
    .expect(400);

  console.log('Response:', JSON.stringify(response.body, null, 2));
  console.log('Should have evaluation error:', response.body.error === 'Rule evaluation failed');
}

// Run tests
async function runTests() {
  try {
    await testValidRule();
    await testMissingContext();
    await testMissingRule();
    await testRuleError();
    console.log('\nAll tests completed!');
    process.exit(0);
  } catch (error) {
    console.error('Test failed:', error);
    process.exit(1);
  }
}

// Start the server and run tests
const server = app.listen(3001, async () => {
  console.log('Test server running on port 3001');
  await runTests();
  server.close();
});

