// Test script for POST /check endpoint
const app = require('./app.js');
const request = require('supertest');

// Create a test instance of the app
const testApp = request(app);

async function testEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Basic rule evaluation
  console.log('Test 1: Basic rule evaluation');
  const response1 = await testApp
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/);

  console.log('Request:', { rule: 'ctx.amount > 100', context: { amount: 150 } });
  console.log('Response:', response1.body);
  console.log('Expected: result should be true\n');

  // Test 2: Boolean false result
  console.log('Test 2: Boolean false result');
  const response2 = await testApp
    .post('/check')
    .send({
      rule: 'ctx.amount < 100',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/);

  console.log('Request:', { rule: 'ctx.amount < 100', context: { amount: 150 } });
  console.log('Response:', response2.body);
  console.log('Expected: result should be false\n');

  // Test 3: Access to request properties
  console.log('Test 3: Access to request properties');
  const response3 = await testApp
    .post('/check')
    .send({
      rule: 'req.method === "POST"',
      context: { someData: 'test' }
    })
    .expect('Content-Type', /json/);

  console.log('Request:', { rule: 'req.method === "POST"', context: { someData: 'test' } });
  console.log('Response:', response3.body);
  console.log('Expected: result should be true (method is POST)\n');

  // Test 4: Complex expression
  console.log('Test 4: Complex expression');
  const response4 = await testApp
    .post('/check')
    .send({
      rule: 'ctx.user.age >= 18 && (ctx.user.country === "US" || ctx.user.country === "CA")',
      context: { 
        user: { 
          age: 21, 
          country: "US",
          name: "John"
        }
      }
    })
    .expect('Content-Type', /json/);

  console.log('Request:', { 
    rule: 'ctx.user.age >= 18 && (ctx.user.country === "US" || ctx.user.country === "CA")',
    context: { user: { age: 21, country: "US", name: "John" } }
  });
  console.log('Response:', response4.body);
  console.log('Expected: result should be true\n');

  // Test 5: Missing rule (error case)
  console.log('Test 5: Missing rule (error case)');
  const response5 = await testApp
    .post('/check')
    .send({
      context: { amount: 150 }
    })
    .expect(400);

  console.log('Request:', { context: { amount: 150 } });
  console.log('Response:', response5.body);
  console.log('Expected: error message about missing rule\n');

  // Test 6: Invalid expression (error case)
  console.log('Test 6: Invalid expression (error case)');
  const response6 = await testApp
    .post('/check')
    .send({
      rule: 'invalid syntax here',
      context: { amount: 150 }
    })
    .expect(400);

  console.log('Request:', { rule: 'invalid syntax here', context: { amount: 150 } });
  console.log('Response:', response6.body);
  console.log('Expected: error message about failed evaluation\n');

  console.log('All tests completed!');
}

// Run the tests
testEndpoint().catch(console.error);

{
  "name": "rules-engine-app",
  "version": "1.0.0",
  "description": "Application with POST /check endpoint for rule evaluation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test_simple.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "keywords": ["rules", "engine", "evaluation"],
  "author": "",
  "license": "ISC"
}

// Simple test demonstration of the POST /check endpoint
const http = require('http');

// Test data for different rule evaluations
const testCases = [
  {
    name: 'Basic rule evaluation (should return true)',
    requestData: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expectedResult: true
  },
  {
    name: 'Boolean false result (should return false)',
    requestData: {
      rule: 'ctx.amount < 100',
      context: { amount: 150 }
    },
    expectedResult: false
  },
  {
    name: 'Complex expression (should return true)',
    requestData: {
      rule: 'ctx.user.age >= 18 && (ctx.user.country === "US" || ctx.user.country === "CA")',
      context: { 
        user: { 
          age: 21, 
          country: "US",
          name: "John"
        }
      }
    },
    expectedResult: true
  },
  {
    name: 'Missing rule (should return error)',
    requestData: {
      context: { amount: 150 }
    },
    expectedResult: null // Expecting error
  },
  {
    name: 'Access to request object (should return true)',
    requestData: {
      rule: 'req !== undefined && req !== null',
      context: { test: 'data' }
    },
    expectedResult: true
  }
];

// Make HTTP requests to test the endpoint
function testEndpoint(testCase) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(testCase.requestData);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/check',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          body: JSON.parse(data)
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

async function runTests() {
  console.log('Testing POST /check endpoint implementation...\n');

