    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST /check endpoint for evaluating rule expressions
app.post('/check', (req, res) => {
  try {
    // Check if rule is provided in request body
    if (!req.body.rule) {
      return res.status(400).json({ error: 'Rule expression is required in request body' });
    }

    // Evaluate the rule expression
    const result = evalRule(req);

    // Return the evaluation result
    res.json({ 
      result: result,
      rule: req.body.rule,
      context: req.body.context || null
    });
  } catch (error) {
    // Handle evaluation errors
    res.status(400).json({ 
      error: 'Failed to evaluate rule expression',
      details: error.message,
      rule: req.body.rule
    });
  }
});

