// Simple HTTP server that implements the POST /check endpoint
const http = require('http');

// Evaluate a caller-supplied rule expression against the request.
function evalRule(expr, context, reqBody) {
  const ctx = { ctx: context, req: reqBody };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

const server = http.createServer((req, res) => {
  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  // Route handling
  if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    }));
    return;
  }

  if (req.method === 'GET' && req.url === '/users') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]));
    return;
  }

  if (req.method === 'POST' && req.url === '/check') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        // Validate required fields
        if (!data.rule) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ 
            error: 'Missing required field: rule' 
          }));
          return;
        }

        if (!data.context) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ 
            error: 'Missing required field: context' 
          }));
          return;
        }

        // Evaluate the rule
        const result = evalRule(data.rule, data.context, data);

        // Return the evaluation result
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          rule: data.rule,
          context: data.context,
          result: result
        }));
      } catch (error) {
        // Handle any errors during rule evaluation
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          error: 'Rule evaluation failed',
          message: error.message
        }));
      }
    });

    return;
  }

  // Handle 404
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ 
    error: 'Not found', 
    path: req.url 
  }));
});

server.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log('\nAvailable endpoints:');
  console.log('  GET  /health');
  console.log('  GET  /users');
  console.log('  POST /check');
  console.log('\nExample POST /check request:');
