// Test script for POST /check endpoint

const http = require('http');

// Test data
const testCases = [
  {
    name: 'Simple numeric comparison',
    body: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expected: true
  },
  {
    name: 'Simple numeric comparison (false)',
    body: {
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    },
    expected: false
  },
  {
    name: 'String comparison',
    body: {
      rule: 'ctx.user === "admin"',
      context: { user: 'admin' }
    },
    expected: true
  },
  {
    name: 'Boolean logic',
    body: {
      rule: 'ctx.isActive && ctx.points > 1000',
      context: { isActive: true, points: 1500 }
    },
    expected: true
  },
  {
    name: 'Access to req properties',
    body: {
      rule: 'req.method === "POST"',
      context: {}
    },
    expected: true
  }
];

// Function to make POST request
function makeRequest(testCase, callback) {
  const postData = JSON.stringify(testCase.body);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      callback(null, res, data);
    });
  });

  req.on('error', (err) => {
    callback(err);
  });

  req.write(postData);
  req.end();
}

// Run tests
console.log('Starting tests for POST /check endpoint...\n');

let passed = 0;
let failed = 0;

testCases.forEach((testCase, index) => {
  setTimeout(() => {
    makeRequest(testCase, (err, res, data) => {
      console.log(`Test: ${testCase.name}`);

      if (err) {
        console.log(`  ❌ Failed: ${err.message}`);
        failed++;
        return;
      }

      try {
        const response = JSON.parse(data);

        if (response.result === testCase.expected) {
          console.log(`  ✅ Passed: Got ${response.result}, expected ${testCase.expected}`);
          passed++;
        } else {
          console.log(`  ❌ Failed: Got ${response.result}, expected ${testCase.expected}`);
          failed++;
        }
      } catch (parseErr) {
        console.log(`  ❌ Failed to parse response: ${parseErr.message}`);
        failed++;
      }

      console.log();

      // If last test, show summary
      if (index === testCases.length - 1) {
        setTimeout(() => {
          console.log('='.repeat(50));
          console.log(`Test Summary:`);
          console.log(`  ✅ Passed: ${passed}`);
          console.log(`  ❌ Failed: ${failed}`);
          console.log(`  📊 Total:  ${passed + failed}`);
          console.log('='.repeat(50));
          process.exit(0);
        }, 100);
      }
    });
  }, index * 100);
});

