// Test script to verify the POST /check endpoint implementation
// Run with: node test_check_endpoint.js

const app = require('./app.js');
const request = require('supertest');

// Since we don't have supertest installed, let's do a manual test
console.log('Testing POST /check endpoint implementation...\n');

// Test cases
const testCases = [
  {
    name: 'Simple numeric comparison',
    requestBody: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expectedResult: true
  },
  {
    name: 'Simple numeric comparison (false case)',
    requestBody: {
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    },
    expectedResult: false
  },
  {
    name: 'String comparison',
    requestBody: {
      rule: 'ctx.status === "approved"',
      context: { status: 'approved' }
    },
    expectedResult: true
  },
  {
    name: 'Complex expression',
    requestBody: {
      rule: 'ctx.age >= 18 && ctx.country === "US"',
      context: { age: 21, country: 'US' }
    },
    expectedResult: true
  },
  {
    name: 'Accessing request object',
    requestBody: {
      rule: 'req.method === "POST"',
      context: {}
    },
    expectedResult: true
  }
];

// Manual test simulation
testCases.forEach((testCase, index) => {
  console.log(`Test ${index + 1}: ${testCase.name}`);
  console.log(`Request body: ${JSON.stringify(testCase.requestBody)}`);

  // Simulate what evalRule would do
  const expr = testCase.requestBody.rule;
  const ctx = testCase.requestBody.context;

  try {
    // This is what evalRule does internally
    const result = Function('ctx', 'req', `return (${expr});`)(
      ctx, 
      { method: 'POST', body: testCase.requestBody }
    );

    console.log(`Expected result: ${testCase.expectedResult}`);
    console.log(`Actual result: ${result}`);
    console.log(`Test ${result === testCase.expectedResult ? 'PASSED' : 'FAILED'}\n`);
  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log('Test FAILED\n');
  }
});

// Test error cases
console.log('Testing error handling...\n');

const errorCases = [
  {
    name: 'Missing rule field',
    requestBody: { context: { amount: 150 } },
    expectedError: 'Missing or invalid rule expression'
  },
  {
    name: 'Invalid JavaScript syntax',
    requestBody: { 
      rule: 'ctx.amount >', // Invalid syntax
      context: { amount: 150 }
    },
    expectedError: 'Rule evaluation failed'
  }
];

errorCases.forEach((testCase, index) => {
  console.log(`Error Test ${index + 1}: ${testCase.name}`);
  console.log(`Request body: ${JSON.stringify(testCase.requestBody)}`);

  // Simulate what the endpoint would do
  if (!testCase.requestBody.rule || typeof testCase.requestBody.rule !== 'string') {
    console.log('Endpoint would return: 400 Bad Request with validation error');
    console.log('Test PASSED (validation would catch this)\n');
  } else {
    try {
      const expr = testCase.requestBody.rule;
      const ctx = testCase.requestBody.context;
      const result = Function('ctx', 'req', `return (${expr});`)(
        ctx, 
        { method: 'POST', body: testCase.requestBody }
      );
      console.log('Test FAILED (should have thrown error)\n');
    } catch (error) {
      console.log(`Endpoint would return: 400 Bad Request with error: ${error.message}`);
      console.log('Test PASSED (error handling would catch this)\n');
    }
  }
});

console.log('All tests completed.');

