}

// Direct test of the evalRule logic without requiring express
console.log('Testing evalRule implementation logic...\n');

// Copy the evalRule function from app.js
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Test cases matching what would be passed to the endpoint
const testCases = [
  {
    name: 'Simple numeric comparison (true)',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      }
    },
    expectedResult: true
  },
  {
    name: 'Simple numeric comparison (false)',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 50 }
      }
    },
    expectedResult: false
  },
  {
    name: 'String comparison',
    req: {
      body: {
        rule: 'ctx.status === "approved"',
        context: { status: 'approved' }
      }
    },
    expectedResult: true
  },
  {
    name: 'Complex expression',
    req: {
      body: {
        rule: 'ctx.age >= 18 && ctx.country === "US"',
        context: { age: 21, country: 'US' }
      }
    },
    expectedResult: true
  },
  {
    name: 'Accessing request object properties',
    req: {
      body: {
        rule: 'req.body.context.amount > 100',
        context: { amount: 150 }
      }
    },
    expectedResult: true,
    note: 'Note: This tests accessing req.body.context directly'
  },
  {
    name: 'Using arithmetic expressions',
    req: {
      body: {
        rule: 'ctx.price * ctx.quantity > 1000',
        context: { price: 50, quantity: 25 }
      }
    },
    expectedResult: true
  }
];

let passed = 0;
let failed = 0;

testCases.forEach((testCase, index) => {
  console.log(`Test ${index + 1}: ${testCase.name}`);
  console.log(`Rule: "${testCase.req.body.rule}"`);
  console.log(`Context: ${JSON.stringify(testCase.req.body.context)}`);

  try {
    const result = evalRule(testCase.req);
    console.log(`Expected: ${testCase.expectedResult}`);
    console.log(`Actual: ${result}`);

    if (result === testCase.expectedResult) {
      console.log('✓ PASSED');
      passed++;
    } else {
      console.log('✗ FAILED');
      failed++;
    }
  } catch (error) {
    console.log(`✗ ERROR: ${error.message}`);
    failed++;
  }

  if (testCase.note) {
    console.log(`Note: ${testCase.note}`);
  }
  console.log('');
});

// Test error cases
console.log('Testing error handling...\n');

const errorCases = [
  {
    name: 'Invalid JavaScript syntax',
    req: {
      body: {
        rule: 'ctx.amount >', // Missing right operand
        context: { amount: 150 }
      }
    },
    expectedToThrow: true
  },
  {
    name: 'Undefined variable in expression',
    req: {
      body: {
        rule: 'ctx.nonexistent > 100',
        context: { amount: 150 }
      }
    },
    // This won't throw, it will return undefined > 100 which is false
    expectedToThrow: false,
    expectedResult: false
  }
];

errorCases.forEach((testCase, index) => {
  console.log(`Error Test ${index + 1}: ${testCase.name}`);
  console.log(`Rule: "${testCase.req.body.rule}"`);

  try {
    const result = evalRule(testCase.req);
    if (testCase.expectedToThrow) {
      console.log(`✗ FAILED: Should have thrown but returned ${result}`);
      failed++;
    } else {
      console.log(`Returned: ${result}`);
      if (testCase.expectedResult !== undefined && result === testCase.expectedResult) {
        console.log('✓ PASSED (returned expected value)');
        passed++;
      } else if (testCase.expectedResult === undefined) {
        console.log('✓ PASSED (no exception thrown)');
        passed++;
      } else {
        console.log('✗ FAILED (wrong return value)');
        failed++;
      }
    }
  } catch (error) {
    if (testCase.expectedToThrow) {
      console.log(`✓ PASSED: Correctly threw error: ${error.message}`);
      passed++;
    } else {
      console.log(`✗ FAILED: Should not have thrown but did: ${error.message}`);
      failed++;
    }
  }
  console.log('');
});

console.log(`\nTest Summary:`);
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);
console.log(`Total: ${passed + failed}`);

