// Test file to demonstrate the POST /check endpoint
const http = require('http');

// Start a minimal server to test the endpoint
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/check') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        // Evaluate a caller-supplied rule expression against the request.
        function evalRule(reqObj) {
          const expr = reqObj.body.rule; // e.g. 'ctx.amount > 100'
          const ctx = { ctx: reqObj.body.context, req: reqObj };
          return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
        }

        if (!data.rule) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing rule expression' }));
          return;
        }

        if (!data.context) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing context' }));
          return;
        }

        const mockReq = { body: data };
        const result = evalRule(mockReq);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ result }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: `Failed to evaluate rule: ${error.message}` }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3001, () => {
