  // Auto-test
  setTimeout(() => {
    const testData = {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    };

    const req = http.request(
      'http://localhost:3001/check',
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      },
      (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
