          console.log('\nAuto-test result:');
          console.log('Request:', JSON.stringify(testData, null, 2));
          console.log('Response:', data);
          server.close();
        });
      }
    );

    req.write(JSON.stringify(testData));
    req.end();
  }, 100);
});

