const app = require('./app.js');
const request = require('supertest');

// Start the server for testing
const server = app.listen(3001, () => {
  console.log('Test server running on port 3001');
});

// Test the /check endpoint
async function testCheckEndpoint() {
  try {
    console.log('Testing POST /check endpoint...\n');

    // Test 1: Valid rule expression
    console.log('Test 1: Valid rule expression');
    const test1 = await request(server)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      })
      .expect('Content-Type', /json/)
      .expect(200);

    console.log('Response:', test1.body);
    console.log('Expected result: true\n');

    // Test 2: Another valid rule expression
    console.log('Test 2: Another valid rule expression');
    const test2 = await request(server)
      .post('/check')
      .send({
        rule: 'ctx.user.age >= 18 && ctx.user.country === "US"',
        context: { user: { age: 21, country: 'US' } }
      })
      .expect('Content-Type', /json/)
      .expect(200);

    console.log('Response:', test2.body);
    console.log('Expected result: true\n');

    // Test 3: Rule that returns false
    console.log('Test 3: Rule that returns false');
    const test3 = await request(server)
      .post('/check')
      .send({
        rule: 'ctx.score < 50',
        context: { score: 75 }
      })
      .expect('Content-Type', /json/)
      .expect(200);

    console.log('Response:', test3.body);
    console.log('Expected result: false\n');

    // Test 4: Missing rule parameter
    console.log('Test 4: Missing rule parameter');
    const test4 = await request(server)
      .post('/check')
      .send({
        context: { amount: 150 }
      })
      .expect('Content-Type', /json/)
      .expect(400);

    console.log('Response:', test4.body);
    console.log('Expected: Missing rule expression error\n');

    // Test 5: Missing context parameter
    console.log('Test 5: Missing context parameter');
    const test5 = await request(server)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100'
      })
      .expect('Content-Type', /json/)
      .expect(400);

    console.log('Response:', test5.body);
    console.log('Expected: Missing context object error\n');

    // Test 6: Invalid rule expression
    console.log('Test 6: Invalid rule expression');
    const test6 = await request(server)
      .post('/check')
      .send({
        rule: 'ctx.amount >',
        context: { amount: 150 }
      })
      .expect('Content-Type', /json/)
      .expect(400);

    console.log('Response:', test6.body);
    console.log('Expected: JavaScript syntax error\n');

  } catch (error) {
    console.error('Test failed:', error.message);
  } finally {
    server.close();
    console.log('Test server closed');
  }
}

